// WF04 F15/F23 — validate the append request and build stable row keys.
// Payload contract (schema_version 1.1.0):
// { sheetId, schema_version, company_id, cycle_id, content_revision, account_id,
//   platform, account_name, format, scheduled_local, scheduled_utc, state,
//   qc_state, preview_url?, remote_url?, theme?, week_of?, title?, notes? }
// The Posts table is the normalized, keyed record: one row per content
// revision and destination account, upserted on row_key =
// cycle_id::content_revision::account_id (F15/F23).
// platform is passed through VERBATIM — there is NO generic-platform fallback
// into any named platform column. Unfamiliar platform labels get their own
// keyed Posts row like any other destination.
const body = $input.first().json.body || {};
const SCHEMA_VERSION = '1.1.0';
const required = ['sheetId', 'company_id', 'cycle_id', 'content_revision', 'account_id',
  'platform', 'account_name', 'format', 'scheduled_local', 'scheduled_utc', 'state', 'qc_state'];
for (const field of required) {
  if (body[field] === undefined || body[field] === null || body[field] === '') {
    throw new Error('missing required field: ' + field);
  }
}
if ((body.schema_version || SCHEMA_VERSION) !== SCHEMA_VERSION) {
  throw new Error('unsupported schema_version: ' + body.schema_version);
}
for (const f of required) { if (typeof body[f] !== 'string' || !body[f].trim()) throw new Error('invalid string: '+f); }
if (!/^[A-Za-z0-9_-]+$/.test(body.sheetId)) throw new Error('invalid sheetId');
for (const f of ['company_id','cycle_id','content_revision','account_id']) { if (body[f].includes('::')) throw new Error('reserved key delimiter: '+f); }
const rowKey = [body.cycle_id, body.content_revision, body.account_id].join('::');
const postsValues = [
  rowKey,                  // A row_key (technical)
  body.company_id,         // B
  body.cycle_id,           // C
  body.content_revision,   // D
  body.account_id,         // E
  body.platform,           // F platform — verbatim, no fallback
  body.account_name,       // G
  body.format,             // H
  body.scheduled_local,    // I
  body.scheduled_utc,      // J
  body.state,              // K
  body.qc_state,           // L
  body.preview_url || '',  // M
  body.remote_url || ''    // N
];
return [{ json: {
  sheetId: body.sheetId,
  rowKey: rowKey,
  postsValues: postsValues,
  postsHeader: ["row_key", "company_id", "cycle_id", "content_revision", "account_id", "platform", "account_name", "format", "scheduled_local", "scheduled_utc", "state", "qc_state", "preview_url", "remote_url"],
  body: body
} }];

// F14 — classify the metadata verification result BEFORE any write.
// The metadata read runs with the SAME googleSheetsOAuth2Api credential the
// append itself uses, so its status code is authoritative for this exact
// access path:
//   404  => 'sheet_not_found'    — nonexistent or deleted sheet ID (identity
//          repair: fix the registered sheetId in the company registry; NEVER
//          silently create a replacement sheet).
//   403  => 'sheet_access_denied' — the credential no longer has access
//          (access repair: re-grant permission on the EXISTING sheet).
//   other error => 'transient'   — bounded retries already applied (3x/2s);
//          surfaced so the caller re-queues without losing the pending row.
// The error response carries repair_required: true + a SPECIFIC repair_action,
// which the caller surfaces as a visible repair task. No sheet is ever created
// as a side effect of a failure.
const src = $('Validate + Build Keys').first().json;
const err = $input.first().json;
const detail = err.error || err;
const status = Number(detail.status || detail.statusCode || detail.httpCode || (detail.response && (detail.response.status || detail.response.statusCode)) || err.status || err.statusCode || (err.response && (err.response.status || err.response.statusCode)));
let repair_state = 'transient';
let repair_action = 'Transient Google Sheets error after 3 bounded retries — keep the row pending and replay it on the next cycle (the idempotency ledger upserts, never duplicates).';
if (status === 404) {
  repair_state = 'sheet_not_found';
  repair_action = 'The registered planner sheet ID ' + src.sheetId + ' does not exist or was deleted (Requested entity was not found). Identity repair: correct the sheetId in the company sheet registry — do NOT create a replacement sheet silently; the pending row replays once the registered ID is verified.';
} else if (status === 403) {
  repair_state = 'sheet_access_denied';
  repair_action = 'The append credential is denied access to sheet ' + src.sheetId + '. Access repair: re-grant the operator credential access to the EXISTING sheet, then replay the pending row (no sheet is created).';
}
return [{ json: {
  success: false,
  repair_required: true,
  repair_state: repair_state,
  repair_action: repair_action,
  sheetId: src.sheetId,
  rowKey: src.rowKey
} }];

const response = $input.first().json;
const src = $('Validate + Build Keys').first().json;
let found = response.values || [];
if (response.range && /!A1:/.test(response.range)) {
 if (JSON.stringify(found[0]) !== JSON.stringify(src.postsHeader)) throw new Error('sheet_schema_invalid_posts_header');
 found = found.slice(1);
}
const matches = [];
for (let i=0;i<found.length;i++) {
 const row=found[i];
 if (row.some(v => v !== '') && row[1] !== src.body.company_id) throw new Error('sheet_company_mismatch');
 if (row[0] === src.rowKey) matches.push(i+2);
}
if(matches.length>1) throw new Error('duplicate_row_key_requires_repair');
return [{json:{existing:matches.length===1,rowNumber:matches[0]||null,sheetId:src.sheetId,rowKey:src.rowKey,postsValues:src.postsValues,allRows:found,body:src.body}}];

// F16 — normalize the Posts write response into receipt fields.
const resp = $input.first().json;
const src = $('Find Posts Row').first().json;
if (!(resp.updates ? resp.updates.updatedRange : resp.updatedRange)) throw new Error('posts_write_missing_updatedRange');
return [{ json: {
  postsUpdatedRange: resp.updates ? resp.updates.updatedRange : resp.updatedRange,
  postsMode: resp.updates ? 'appended' : 'updated',
  sheetId: src.sheetId,
  rowKey: src.rowKey,
  allRows: src.allRows,
  body: src.body
} }];

// F23 — derive the Weekly Overview summary row FROM the Posts rows of this
// cycle/content revision. Weekly Overview stays a summary view; the Posts
// table remains the per-account source of truth.
// - Known platform columns (live 20-column order) aggregate per-account
//   states for that cycle/revision.
// - Platforms with no overview column (X, Google Business Profile, unfamiliar
//   labels) appear ONLY in the Posts table. Nothing is funneled into the
//   TikTok column or any other named column.
// - New summary rows carry a technical key in column U (_row_key) so they are
//   upserted, never duplicated. Legacy overview rows without the key are
//   retained untouched.
const ovRows = ($input.first().json.values || []);
const src = $('Find Posts Row').first().json;
const body = src.body;
const ovKey = ['OV', body.cycle_id, body.content_revision].join('::');
const PLATFORM_COLUMNS = { 'Facebook': 6, 'Instagram': 7, 'LinkedIn': 8, 'YouTube': 9, 'TikTok': 10, 'Pinterest': 11 };
const rows = src.allRows.filter(r => r[0] !== src.rowKey).concat([src.postsValues]);
const byPlatform = {};
for (const r of rows) {
  if ((r[2] || '') !== body.cycle_id || (r[3] || '') !== body.content_revision) continue;
  const platform = r[5] || '';
  const label = r[6] || platform;
  if (!byPlatform[platform]) byPlatform[platform] = [];
  byPlatform[platform].push(label + ': ' + (r[10] || body.state || ''));
}
// Live 20-column order: Week Of, Theme of the Week, Research, Core Content,
// Images, Videos, Facebook, Instagram, LinkedIn, YouTube, TikTok, Pinterest,
// Carousels, Blog, Podcast, Email, QC, Scheduled, Overall, Notes (+ U key).
const values = new Array(21).fill('');
values[0] = body.week_of || body.cycle_id;
values[1] = body.theme || '';
values[3] = body.title || body.core_content || '';
values[16] = rows.filter(r => r[2] === body.cycle_id && r[3] === body.content_revision).map(r => (r[6] || r[5]) + ': ' + (r[11] || '')).join('; ');
values[17] = body.scheduled_local || '';
values[18] = body.state;
values[19] = body.notes || '';
for (const platform of Object.keys(PLATFORM_COLUMNS)) {
  if (byPlatform[platform]) values[PLATFORM_COLUMNS[platform]] = byPlatform[platform].join('; ');
}
values[20] = ovKey;
let ovRowNumber = null;
for (let i = 0; i < ovRows.length; i++) {
  if ((ovRows[i][20] || '') === ovKey) { ovRowNumber = i + 2; break; }
}
if (ovRowNumber && body.notes === undefined) values[19] = ovRows[ovRowNumber-2][19] || '';
return [{ json: {
  ovExisting: ovRowNumber !== null,
  ovRowNumber: ovRowNumber,
  ovValues: values,
  sheetId: src.sheetId,
  rowKey: src.rowKey,
  postsUpdatedRange: $('Normalize Posts Write').first().json.postsUpdatedRange,
  postsMode: $('Normalize Posts Write').first().json.postsMode
} }];

// F16 — response receipt: sheetId, updatedRange(s), row keys, schema version.
const ovResp = $input.first().json;
const posts = $('Normalize Posts Write').first().json;
const src = $('Find Posts Row').first().json;
if (!(ovResp.updates ? ovResp.updates.updatedRange : ovResp.updatedRange)) throw new Error('overview_write_missing_updatedRange');
return [{ json: { receipt: {
  success: true,
  sheetId: posts.sheetId,
  posts_updatedRange: posts.postsUpdatedRange,
  overview_updatedRange: ovResp.updates ? ovResp.updates.updatedRange : ovResp.updatedRange,
  row_key: posts.rowKey,
  overview_key: ['OV', src.body.cycle_id, src.body.content_revision].join('::'),
  mode: posts.postsMode === 'appended' ? 'appended' : 'upserted',
  schema_version: '1.1.0'
} } }];

// F24/F38 — after the manifest row is committed (upsert or append), resolve the
// actual Images row number from the write response so the trusted =IMAGE
// formula lands in the SAME row the manifest describes. Video rows route to
// the Videos tab writes via videosRow.
const resp = $input.first().json;
const prior = $('Find Asset Row (F24)').first().json;
let rowNumber = prior.assetRowNumber;
const range = (resp.updates ? resp.updates.updatedRange : resp.updatedRange) || '';
if (!rowNumber && range) {
  const m = range.match(/:N(\d+)/);
  if (m) rowNumber = parseInt(m[1], 10);
}
if (!rowNumber) throw new Error('asset_write_missing_updatedRange');
return [{ json: {
  sheetId: prior.sheetId,
  assetRowNumber: rowNumber,
  assetExisting: prior.assetExisting,
  imagesFormula: prior.imagesFormula,
  videosRow: prior.videosRow,
  assetManifest: prior.assetManifest,
  assetRepair: prior.assetRepair,
  receipt: prior.receipt
} }];

// F24 — validate + persist the asset manifest row and build the Images-tab
// write. Trusted =IMAGE("https://…",1) formulas are generated ONLY here, ONLY
// for URLs that pass validation: https scheme, no quotes/backslashes/control
// characters, and a Sheets-fetchable permanent CDN host. Private Drive page
// links and soon-expiring URLs are refused into a visible repair state — they
// are never written as formulas (and never as RAW either). The manifest row
// itself (content id, ratio, dimensions, alt text, URLs) is RAW values keyed on
// asset_id; the formula goes into the Images tab's designated preview column.
const receipt = $('Build Receipt').first().json.receipt;
const src = $('Find Posts Row').first().json;
const body = src.body;
const asset = body.asset || null;
if (!asset) return [{ json: { sheetId:body.sheetId, receipt: receipt, assetManifest: null, imagesFormula: null, assetRepair: null } }];
const kind = String(asset.kind || 'image');
if (!['image','video'].includes(kind)) throw new Error('unsupported_asset_kind');
const contentId = String(asset.content_id || (body.cycle_id + '::' + body.content_revision));
const assetId = String(asset.asset_id || (contentId + '::' + body.account_id + '::' + kind));
const previewUrl = String(asset.preview_url || body.preview_url || '');
const originalUrl = String(asset.original_url || '');
// URL validation — reject what Sheets cannot render.
let urlRepair = null;
if (!previewUrl) {
  urlRepair = 'asset_missing_url';
} else if (!/^https:\/\//i.test(previewUrl)) {
  urlRepair = 'asset_url_not_https';
} else if (/["'\\\x00-\x1f]/.test(previewUrl)) {
  urlRepair = 'asset_url_unsafe_chars';
} else if (/drive\.google\.com\/(file\/d|open\?id=)/i.test(previewUrl) || /drive\.usercontent\.google\.com/i.test(previewUrl) === false && /docs\.google\.com\/(document|spreadsheets|presentation|uc\?)/i.test(previewUrl)) {
  urlRepair = 'asset_url_not_fetchable'; // private Drive page link, not a direct image
}
// n8n Code runners do not consistently expose the browser URL global.
// Parse only the supported HTTPS CDN URL subset without ambient modules.
function safeUrl(value) {
 if (typeof value !== 'string' || /[\s"'\\\x00-\x1f]/.test(value)) return false;
 const match=/^https:\/\/([A-Za-z0-9.-]+)(?::([0-9]{1,5}))?(?:\/[^?#]*)?(?:\?([^#]*))?(?:#.*)?$/.exec(value);
 if(!match) return false;
 const host=match[1].toLowerCase();
 if(host.length>253 || host.split('.').some(label=>!label || label.length>63 || !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(label)))return false;
 if(match[2] && (Number(match[2])<1 || Number(match[2])>65535))return false;
 if(/(^|\.)(drive|docs)\.google\.com$/.test(host))return false;
 try {
   return !(match[3]||'').split('&').some(part=>/^(expires|expiry|x-amz-|x-goog-|signature|token)/i.test(decodeURIComponent(part.split('=')[0].replace(/\+/g,' '))));
 } catch {return false;}
}
if (!safeUrl(previewUrl)) urlRepair = urlRepair || 'asset_url_not_permanent';
const ratio = String(asset.ratio || '');
const width = asset.width != null ? String(asset.width) : '';
const height = asset.height != null ? String(asset.height) : '';
const altText = String(asset.alt_text || '');
const qcState = String(asset.qc_state || body.qc_state || '');
// Manifest row (RAW values) — A asset_key, then the manifest fields.
const assetKey = ['ASSET', body.company_id, contentId, assetId].join('::');
const manifestValues = [assetKey, contentId, assetId, body.company_id, body.cycle_id,
  body.content_revision, kind, previewUrl, originalUrl, ratio, width, height, altText, qcState];
const manifestHeader = ["asset_key", "content_id", "asset_id", "company_id", "cycle_id", "content_revision", "kind", "preview_url", "original_url", "ratio", "width", "height", "alt_text", "qc_state"];
let imagesFormula = null;
if (kind === 'image' && !urlRepair) {
  imagesFormula = '=IMAGE("' + previewUrl + '", 1)';
}
// F38 — video evidence: the Videos tab carries the poster (trusted =IMAGE of
// the poster CDN URL — a video cell is a visible poster plus a playback link,
// never a promised native MP4 player), duration, ratio, version, QC and the
// client-bound 'Watch video' HYPERLINK to the CC player route. The PUBLISHED
// destination URL is written separately only after posting; client drafts are
// NEVER uploaded to public YouTube just to preview — a YouTube smart-chip note
// is added only when the published destination actually is YouTube.
let videosRow = null;
if (kind === 'video' && !urlRepair) {
  const watchUrl = String(asset.watch_url || '');
  if (!safeUrl(watchUrl)) {
    // An untrusted watch URL is refused — never written as a HYPERLINK.
    if (!urlRepair) urlRepair = 'asset_watch_url_invalid';
  } else {
    const posterUrl = String(asset.poster_url || previewUrl || '');
    if (!safeUrl(posterUrl)) urlRepair = 'asset_poster_url_invalid';
    const videoKey = ['VIDEO', body.company_id, contentId, assetId].join('::');
    const publishedUrl = String(asset.published_url || '');
    const isYouTube = Boolean(asset.youtube);
    let watchCell = '=HYPERLINK("' + watchUrl + '", "Watch video")';
    if (isYouTube && publishedUrl) {
      // YouTube smart-chip note only when applicable (published YouTube link).
      // Keep formula syntactically valid; published URL is a separate RAW cell.
    }
    videosRow = {
      video_key: videoKey,
      header: ["video_key", "content_id", "asset_id", "company_id", "cycle_id", "content_revision", "version", "poster_url", "published_url", "watch_url", "duration_seconds", "ratio", "captions", "qc_state"],
      values: [videoKey, contentId, assetId, body.company_id, body.cycle_id,
        body.content_revision, String(asset.version || body.content_revision || ''),
        posterUrl, publishedUrl, watchUrl,
        String(asset.duration_seconds != null ? asset.duration_seconds : ''),
        String(asset.ratio || ratio || ''), String(asset.captions ? 'captions' : ''), qcState],
      posterFormula: posterUrl ? '=IMAGE("' + posterUrl + '", 1)' : null,
      watchFormula: watchCell
    };
  }
}
return [{ json: {
  receipt: urlRepair ? {...receipt, asset_repair: {repair_required:true,repair_state:urlRepair,asset_id:assetId}, partial:true} : receipt,
  sheetId: body.sheetId,
  assetManifest: urlRepair ? null : { asset_key: assetKey, values: manifestValues, header: manifestHeader },
  imagesFormula: imagesFormula,
  videosRow: urlRepair ? null : videosRow,
  assetRepair: urlRepair ? { repair_required: true, repair_state: urlRepair, repair_action: 'Asset URL for ' + contentId + ' failed validation (' + urlRepair + '). Surface a visible repair task; re-upload to the permanent CDN and re-run the cycle. The healthy Posts row may already be saved; this asset was not written.', asset_id: assetId } : null
} }];

// F24/F38 — find the manifest row for this asset_key (upsert, never duplicate).
const found = ($input.first().json.values || []);
const src = $('Build Asset Manifest (F24)').first().json;
let rowNumber = null;
if (src.assetManifest) {
  for (let i = 0; i < found.length; i++) {
    if ((found[i][0] || '') === src.assetManifest.asset_key) { if (rowNumber !== null) throw new Error('duplicate_asset_key_requires_repair'); rowNumber = i + 2; }
  }
}
return [{ json: {
  assetExisting: src.assetManifest ? rowNumber !== null : false,
  assetRowNumber: rowNumber,
  assetManifest: src.assetManifest,
  imagesFormula: src.imagesFormula,
  videosRow: src.videosRow,
  assetRepair: src.assetRepair,
  sheetId: src.sheetId,
  receipt: src.receipt
} }];

// F38 — find the Videos row for this video_key (upsert, never duplicate).
const found = ($input.first().json.values || []);
const prior = $('Normalize Asset Write (F24)').first().json;
let rowNumber = null;
if (prior.videosRow) {
  for (let i = 0; i < found.length; i++) {
    if ((found[i][0] || '') === prior.videosRow.video_key) { if (rowNumber !== null) throw new Error('duplicate_video_key_requires_repair'); rowNumber = i + 2; }
  }
}
return [{ json: {
  videoExisting: prior.videosRow ? rowNumber !== null : false,
  videoRowNumber: rowNumber,
  videosRow: prior.videosRow,
  sheetId: prior.sheetId,
  receipt: prior.receipt
} }];

const resp=$input.first().json, prior=$('Find Video Row (F38)').first().json;
const range=(resp.updates ? resp.updates.updatedRange : resp.updatedRange)||'';
const match=range.match(/:N(\d+)/);
const rowNumber=prior.videoRowNumber || (match ? Number(match[1]) : null);
if(!rowNumber) throw new Error('video_write_missing_updatedRange');
const tab=$('Verify Sheet Metadata (F14)').first().json.sheets.find(s=>s.properties.title==='Videos');
if(!tab) throw new Error('sheet_schema_missing_tab: Videos');
const requests=[];
for(const [columnIndex,formula] of [[17,prior.videosRow.posterFormula],[18,prior.videosRow.watchFormula]]) if(formula) requests.push({updateCells:{rows:[{values:[{userEnteredValue:{formulaValue:formula}}]}],fields:'userEnteredValue',start:{sheetId:tab.properties.sheetId,rowIndex:rowNumber-1,columnIndex}}});
return [{json:{videoFormulaRequests:requests,videoRowNumber:rowNumber,videoExisting:prior.videoExisting,receipt:prior.receipt}}];

// Resolve numeric tab IDs; field masks and zero-based row ranges are required.
const sheets=$input.first().json.sheets || [];
const ids=Object.fromEntries(sheets.map(s=>[s.properties.title,s.properties.sheetId]));
const posts=$('Normalize Posts Write').first().json;
const asset=$('Build Asset Manifest (F24)').first().json;
const requests=[];
function dimension(tab,dimension,start,size) { if(ids[tab]!==undefined && start>=0) requests.push({updateDimensionProperties:{range:{sheetId:ids[tab],dimension,startIndex:start,endIndex:start+1},properties:{pixelSize:size},fields:'pixelSize'}}); }
if(posts.postsMode === 'appended') for(const [column,width] of [[5,170],[6,170],[8,110],[9,110],[10,140],[11,130],[12,220]]) dimension('Posts','COLUMNS',column,width);
const postMatch=(posts.postsUpdatedRange||'').match(/:N(\d+)/);
if(postMatch && posts.postsMode === 'appended') dimension('Posts','ROWS',Number(postMatch[1])-1,133);
if(asset.assetManifest) {
 const state=$('Normalize Asset Write (F24)').first().json;
 if(!state.assetExisting) dimension('Images','COLUMNS',15,220);
 if(state.assetRowNumber && !state.assetExisting) dimension('Images','ROWS',state.assetRowNumber-1,275);
 if(state.videosRow) {
  const video=$('Build Video Formula Writes (F38)').first().json;
  if(!video.videoExisting) { dimension('Videos','COLUMNS',17,220); dimension('Videos','COLUMNS',18,170);
  dimension('Videos','ROWS',video.videoRowNumber-1,275); }
 }
}
return [{json:{receipt:asset.receipt,resizeRequests:requests,resizeApplied:requests.length>0}}];

const src = $('Validate + Build Keys').first().json;
const meta = $input.first().json;
const owners=(meta.developerMetadata || []).filter(m=>m.metadataKey==='skill35_company_id').map(m=>m.metadataValue);
if(owners.length!==1 || owners[0]!==src.body.company_id) throw new Error('sheet_company_binding_missing_or_mismatch');
const titles = (meta.sheets || []).map(s => s.properties.title);
const required = ['Posts', 'Weekly Overview'];
if (src.body.asset) required.push('Images');
if (src.body.asset && src.body.asset.kind === 'video') required.push('Videos');
for (const title of required) if (!titles.includes(title)) throw new Error('sheet_schema_missing_tab: '+title);
return [{json: src}];
